INSERT INTO products (id, category_id, name, slug, description, material, base_price, stock_quantity, image_url, is_active, created_at) VALUES (1, 1, 'Everyday Twill Cap', 'everyday-twill-cap', 'หมวกแก๊ป 6 แผงรุ่นซิกเนเจอร์ ผ้าทวิลคอตตอนหนา 380 แกรม ทรง Unstructured ปีกโค้งพร้อมใส่ สายปรับหัวเข็มขัดสแตนเลส ยิ่งใส่ยิ่งนุ่ม', 'Heavyweight cotton twill 380g', 1290, 0, 'https://images.unsplash.com/photo-1517941823-815bea90d291?auto=format&fit=crop&w=900&q=80', 1, datetime('now', '-85 days'));
INSERT INTO products (id, category_id, name, slug, description, material, base_price, stock_quantity, image_url, is_active, created_at) VALUES (2, 1, 'Cord Six-Panel Cap', 'cord-six-panel-cap', 'หมวกแก๊ปผ้าลูกฟูกร่องใหญ่ ทรงโปรไฟล์ต่ำแบบ Structured ปักโลโก้โทนเดียวกันด้านหลัง แถบซับเหงื่อคอตตอนคงรูปทรง', 'Wide-wale corduroy', 1390, 0, 'https://images.unsplash.com/photo-1466992133056-ae8de8e22809?auto=format&fit=crop&w=900&q=80', 1, datetime('now', '-80 days'));
INSERT INTO products (id, category_id, name, slug, description, material, base_price, stock_quantity, image_url, is_active, created_at) VALUES (3, 1, 'Nylon Runner Cap', 'nylon-runner-cap', 'หมวกวิ่งผ้าไนลอนรีไซเคิล น้ำหนักเพียง 48 กรัม เจาะรูระบายอากาศด้วยเลเซอร์ ปีกพับได้ แห้งไวภายในไม่กี่นาที', 'Recycled nylon', 1190, 0, 'https://images.unsplash.com/photo-1645266729222-17cd32e06fd0?auto=format&fit=crop&w=900&q=80', 1, datetime('now', '-75 days'));
INSERT INTO products (id, category_id, name, slug, description, material, base_price, stock_quantity, image_url, is_active, created_at) VALUES (4, 2, 'Tactile Ripstop Bucket', 'tactile-ripstop-bucket', 'หมวกบักเก็ตผ้า Ripstop กันละอองน้ำ ปีกเย็บเสริมหลายแนวคงทรงสวย ตาไก่ทองเหลืองระบายอากาศ 2 จุด พร้อมช่องซ่อนกุญแจ', 'Technical ripstop', 1490, 0, 'https://images.unsplash.com/photo-1617916918894-7bc1ea780bb2?auto=format&fit=crop&w=900&q=80', 1, datetime('now', '-70 days'));
INSERT INTO products (id, category_id, name, slug, description, material, base_price, stock_quantity, image_url, is_active, created_at) VALUES (5, 2, 'Corduroy Bucket', 'corduroy-bucket', 'หมวกบักเก็ตผ้าลูกฟูกเนื้อนุ่ม ทรงลึก ปีกลาดเล็กน้อยแบบวินเทจ ซับในผ้าป็อปลินคอตตอนพิมพ์ลาย', 'Wide-wale corduroy', 1590, 0, 'https://images.unsplash.com/photo-1627681828965-048a32cdf16f?auto=format&fit=crop&w=900&q=80', 1, datetime('now', '-65 days'));
INSERT INTO products (id, category_id, name, slug, description, material, base_price, stock_quantity, image_url, is_active, created_at) VALUES (6, 2, 'Reversible Terry Bucket', 'reversible-terry-bucket', 'หมวกบักเก็ตใส่ได้ 2 ด้าน ด้านหนึ่งผ้าขนหนู Terry อีกด้านผ้าทวิลเรียบ เหมาะกับทะเล ซักเครื่องได้ที่ 30 องศา', 'Cotton terry / twill', 1690, 0, 'https://images.unsplash.com/photo-1622445275576-721325763afe?auto=format&fit=crop&w=900&q=80', 1, datetime('now', '-60 days'));
INSERT INTO products (id, category_id, name, slug, description, material, base_price, stock_quantity, image_url, is_active, created_at) VALUES (7, 3, 'Heavy Rib Beanie', 'heavy-rib-beanie', 'บีนนี่ถักลาย Rib 2x2 แน่นหนา ขนแกะเมอริโนเกรดพิเศษ พับขอบ 2 ชั้น ระบายอากาศดี ไม่คัน อุ่นโดยไม่หนาเทอะทะ', 'Extra-fine merino wool', 890, 0, 'https://images.unsplash.com/photo-1618354691792-d1d42acfd860?auto=format&fit=crop&w=900&q=80', 1, datetime('now', '-55 days'));
INSERT INTO products (id, category_id, name, slug, description, material, base_price, stock_quantity, image_url, is_active, created_at) VALUES (8, 3, 'Fisherman Beanie', 'fisherman-beanie', 'บีนนี่ทรงสั้นแบบชาวประมง ใส่แล้วอยู่เหนือหู ถักลาย Rib ผ้าเมอริโน พร้อมป้ายทอ K''Sante', 'Ribbed merino wool', 790, 0, 'https://images.unsplash.com/photo-1510598969022-c4c6c5d05769?auto=format&fit=crop&w=900&q=80', 1, datetime('now', '-50 days'));
INSERT INTO products (id, category_id, name, slug, description, material, base_price, stock_quantity, image_url, is_active, created_at) VALUES (9, 3, 'Mohair Fuzz Beanie', 'mohair-fuzz-beanie', 'บีนนี่ไหมพรมผสมโมแฮร์ ผิวฟูนุ่มเหมือนก้อนเมฆ ทรงหลวมสบาย พับขอบ น้ำหนักเบามาก', 'Mohair blend', 1090, 0, 'https://images.unsplash.com/photo-1648483092137-6e63796c8b06?auto=format&fit=crop&w=900&q=80', 1, datetime('now', '-45 days'));
INSERT INTO products (id, category_id, name, slug, description, material, base_price, stock_quantity, image_url, is_active, created_at) VALUES (10, 4, 'Atelier Wool Beret', 'atelier-wool-beret', 'เบเร่ต์ผ้าสักหลาดขนแกะแบบคลาสสิก ขอบหุ้มหนังแท้ มีจุกด้านบนแบบฝรั่งเศส ใส่ไปสักสัปดาห์จะเข้ารูปศีรษะเอง', 'Boiled wool felt', 1290, 0, 'https://images.unsplash.com/photo-1642795752867-37df82428008?auto=format&fit=crop&w=900&q=80', 1, datetime('now', '-40 days'));
INSERT INTO products (id, category_id, name, slug, description, material, base_price, stock_quantity, image_url, is_active, created_at) VALUES (11, 4, 'Knit Beret', 'knit-beret', 'เบเร่ต์ถักไหมพรมเมอริโนนุ่ม ถักแบนแล้วขึ้นรูปด้วยมือ ใส่เอียงข้างหรือดึงไปด้านหลังก็สวย', 'Soft merino knit', 990, 0, 'https://images.unsplash.com/photo-1758887249062-9a544a74aa29?auto=format&fit=crop&w=900&q=80', 1, datetime('now', '-35 days'));
INSERT INTO products (id, category_id, name, slug, description, material, base_price, stock_quantity, image_url, is_active, created_at) VALUES (12, 4, 'Leather Trim Beret', 'leather-trim-beret', 'เบเร่ต์สักหลาดรุ่นพรีเมียม ขอบหนังวัวแท้ เย็บมือ ผลิตจำนวนจำกัด', 'Wool felt with leather trim', 1890, 0, 'https://images.unsplash.com/photo-1713952704614-76630700a4b4?auto=format&fit=crop&w=900&q=80', 1, datetime('now', '-30 days'));
